@startuml

class Resident {
  + name : string
  + street_address : string
  + phone_number : string
  + email : string
}

class Item {
  + description : string
  + dimensions : string
  + weight : float
  + category : string
}

class Vehicle {
  + storage_space : float
}

class Route {
  + date : date
}

class VolunteerDriver {
  + available_days : string[]
}

class Pickup {
  + scheduled_time : time
}

class Location {
  + name : string
}

class DistributionCenter {
  + address : string
}

class FoodBank {
  + name : string
}

class Client {
  + home_address : string
  + needed_categories : string[]
}

class Article {
  + description : string
  + category : string
  + rfid_tag : string
}

Location "1" -- "*" DistributionCenter
Location "1" -- "*" FoodBank

Resident "1" -- "*" Item : provides
Resident "1" -- "0..1" Client : is a
Client "1" -- "*" Article : receives

VolunteerDriver "1" -- "0..*" Route : drives
Route "1" -- "1" Vehicle : assigned to
Route "1" -- "*" Pickup : contains
Pickup "1" -- "1" Resident : at
Pickup "1" -- "1" Item : collects

Vehicle "1" -- "*" Pickup : performs

Article "*" -- "1" DistributionCenter : processed at
Article "1" -- "1" Item : is a

@enduml

